class EmbedSymmetricTensorDegeneratePoints(Node):

    def __init__(self, parent_node_id : str, radius : float = 3.0, color_scheme : List[str] = ["#ffffff", "#ff8cc6"]):
        if correctness_checks_on():
            if len(color_scheme) != 2:
                raise Exception("color_scheme list should have two")

            for elt in color_scheme:
                if not is_hex_string(elt):
                    raise Exception(f"Element {elt} in color_scheme is not a hex string")

            del elt

        super().__init__(parent_node_id, types.SymmetricTensorDegeneratePoints, types.SymmetricTensorDegeneratePointsEmbedding, locals(), False, True)

        self.radius = radius
        self.color_scheme = color_scheme

    @classmethod
    def chat_description(cls):
        return "queued embedding symmetric tensor field degenerate points"

    @classmethod
    def description(cls):
        return 'Create a geometric embedding of the degenerate points of symmetric tensor field data.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'A node of type symmetric_tensor_dp which corresponds to some '
                           'degenerate points that should be visualized.',
         'radius': 'The radius of the spheres that will be used to visualize the degenerate '
                   'points.',
         'color_scheme': 'A list of two hex strings that respectively correspond to the colors that '
                   'will be used to visualize trisectors and wedges.'}

    def compatible_to_visualize(self, other):
        if issubclass(other.node_type, types.TrackedSymmetricTensorDegeneratePointsEmbedding) and \
           self.parent_node_id == other.parent_node.parent_node_id:

            return False, "Cannot visualize a symmetric tensor field's set of degenerate points both tracked and "\
                          "untracked at the same time. They will overlap."

        return True, ""

    def _evaluation_logic(self, parent_data, time_step):
        return types.SymmetricTensorDegeneratePointsEmbedding(parent_data.points, self.radius, "CriticalType", color_list_to_lut(self.color_scheme))

